+
+            <div class="form-panel">
+              <h2 id="contact-heading">Contact support</h2>
+              <p>Required fields are marked with <span aria-hidden="true">*</span>.</p>
+
+              <form id="support-form" novalidate>
+                <div class="form-grid">
+                  <div class="form-field" data-field="fullName">
+                    <label for="fullName">
+                      Full name <span class="required-indicator" aria-hidden="true">*</span>
