    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <main id="maincontent" tabindex="-1">
      <div class="page-shell">
        <section class="hero" aria-labelledby="page-title">
          <p class="eyebrow">Support</p>
          <h1 id="page-title">Get help from our support team</h1>
          <p>
            Share your contact details and we will follow up with the right next
            step for your account, billing, or product questions.
          </p>
        </section>

        <section class="support-card" aria-labelledby="contact-heading">
          <div class="support-layout">
            <div class="support-summary">
              <h2>What happens next</h2>
              <p>
                A support specialist reviews every request and replies with the
                fastest path to resolution.
              </p>
              <ul class="support-points">
                <li>
                  <strong>Fast triage</strong>
                  We route your request to the right team right away.
                </li>
                <li>
                  <strong>Clear updates</strong>
                  Expect a response using the email address you share below.
                </li>
                <li>
                  <strong>Optional callback</strong>
                  Add a phone number if you would like help by phone.
                </li>
              </ul>
            </div>

            <div class="form-panel">
              <h2 id="contact-heading">Contact support</h2>
              <p>Required fields are marked with <span aria-hidden="true">*</span>.</p>

              <form id="support-form" novalidate>
                <div class="form-grid">
                  <div class="form-field" data-field="fullName">
                    <label for="fullName">
                      Full name <span class="required-indicator" aria-hidden="true">*</span>
                    </label>
                    <input
                      id="fullName"
                      name="fullName"
                      type="text"
                      autocomplete="name"
                      required
                    />
                    <p id="fullName-error" class="error-message" hidden></p>
                  </div>

                  <div class="form-field" data-field="email">
                    <label for="email">
                      Email address <span class="required-indicator" aria-hidden="true">*</span>
                    </label>
                    <input
                      id="email"
                      name="email"
                      type="email"
                      inputmode="email"
                      autocomplete="email"
                      required
                    />
                    <p id="email-error" class="error-message" hidden></p>
                  </div>

                  <div class="form-field" data-field="phone">
                    <label for="phone">Phone number <span class="helper-text">(optional)</span></label>
                    <input
                      id="phone"
                      name="phone"
                      type="tel"
                      inputmode="tel"
                      autocomplete="tel"
                      aria-describedby="phone-help"
                    />
                    <p id="phone-help" class="helper-text">
                      Use digits with an optional country code, for example
                      +1 555 123 4567.
                    </p>
                    <p id="phone-error" class="error-message" hidden></p>
                  </div>
                </div>

                <div class="form-actions">
                  <button type="submit">Send request</button>
                  <div id="form-status" class="form-status" role="status" aria-live="polite"></div>
                </div>
              </form>
            </div>
          </div>
        </section>
      </div>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const statusRegion = document.getElementById("form-status");

      const fieldConfig = {
        fullName: {
          input: document.getElementById("fullName"),
          error: document.getElementById("fullName-error"),
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your full name.";
            }

            return "";
          },
        },
        email: {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your email address.";
            }

            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailPattern.test(value.trim())) {
              return "Error: Enter a valid email address, for example name@example.com.";
            }

            return "";
          },
        },
        phone: {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          helpId: "phone-help",
          validate(value) {
            if (!value.trim()) {
              return "";
            }

            const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
            if (!phonePattern.test(value.trim())) {
              return "Error: Enter a phone number using digits, spaces, dashes, or parentheses.";
            }

            return "";
          },
        },
      };

      function updateFieldState(fieldName) {
        const field = fieldConfig[fieldName];
        const message = field.validate(field.input.value);
        const wrapper = field.input.closest(".form-field");
        const describedBy = [];

        if (field.helpId) {
          describedBy.push(field.helpId);
        }

        if (message) {
          field.error.textContent = message;
          field.error.hidden = false;
          describedBy.push(field.error.id);
          field.input.setAttribute("aria-invalid", "true");
          wrapper.classList.add("field-invalid");
        } else {
          field.error.textContent = "";
          field.error.hidden = true;
          field.input.removeAttribute("aria-invalid");
          wrapper.classList.remove("field-invalid");
        }

        if (describedBy.length > 0) {
          field.input.setAttribute("aria-describedby", describedBy.join(" "));
        } else {
          field.input.removeAttribute("aria-describedby");
        }

        return message;
      }

      Object.keys(fieldConfig).forEach((fieldName) => {
        const field = fieldConfig[fieldName];

        field.input.addEventListener("input", () => {
          if (!field.error.hidden) {
            updateFieldState(fieldName);
          }

          if (statusRegion.textContent) {
            statusRegion.textContent = "";
            statusRegion.dataset.state = "";
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusRegion.textContent = "";
        statusRegion.dataset.state = "";

        const invalidFields = Object.keys(fieldConfig).filter((fieldName) => {
          return Boolean(updateFieldState(fieldName));
        });

        if (invalidFields.length > 0) {
          fieldConfig[invalidFields[0]].input.focus();
          return;
        }

        statusRegion.textContent = "Your support request has been sent.";
        statusRegion.dataset.state = "success";
        form.reset();

        Object.keys(fieldConfig).forEach((fieldName) => {
          updateFieldState(fieldName);
        });
      });
    </script>
