 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Contact support - Acme</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f3f6fb;
         --surface: rgba(255, 255, 255, 0.88);
         --surface-strong: #ffffff;
         --text: #162033;
         --muted: #5f6b85;
         --border: #c8d2e5;
         --accent: #335cff;
         --accent-strong: #1f46dd;
         --error: #b42318;
         --success-bg: #ecfdf3;
         --success-text: #05603a;
         --shadow: 0 24px 60px rgba(20, 36, 72, 0.14);
         --radius-lg: 24px;
         --radius-md: 16px;
         --radius-sm: 12px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(51, 92, 255, 0.14), transparent 30%),
           radial-gradient(circle at top right, rgba(72, 187, 120, 0.12), transparent 28%),
           linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       }

       a {
         color: inherit;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         z-index: 10;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--text);
         color: #fff;
         text-decoration: none;
         transform: translateY(-160%);
         transition: transform 0.2s ease;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       main {
         display: grid;
         place-items: center;
         padding: 3rem 1.25rem;
       }

       .page-shell {
         width: min(100%, 1080px);
         display: grid;
         gap: 1.5rem;
         grid-template-columns: minmax(0, 1fr);
       }

       .hero,
       .support-card {
         background: var(--surface);
         backdrop-filter: blur(12px);
         border: 1px solid rgba(255, 255, 255, 0.7);
         border-radius: var(--radius-lg);
         box-shadow: var(--shadow);
       }

       .hero {
         padding: 2rem;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         margin: 0 0 1rem;
         padding: 0.4rem 0.75rem;
         border-radius: 999px;
         background: rgba(51, 92, 255, 0.1);
         color: var(--accent-strong);
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.02em;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 3.35rem);
         line-height: 1.05;
       }

       .hero p {
         max-width: 42rem;
         margin: 1rem 0 0;
         color: var(--muted);
         font-size: 1.05rem;
         line-height: 1.6;
       }

       .support-card {
         overflow: hidden;
       }

       .support-layout {
         display: grid;
       }

       .support-summary,
       .form-panel {
         padding: 2rem;
       }

       .support-summary {
         background: linear-gradient(180deg, rgba(51, 92, 255, 0.96), rgba(27, 60, 201, 0.96));
         color: #fff;
       }

       .support-summary h2,
       .form-panel h2 {
         margin: 0 0 0.75rem;
         font-size: 1.45rem;
       }

       .support-summary p,
       .form-panel > p {
         margin: 0;
         line-height: 1.6;
       }

       .support-points {
         margin: 1.5rem 0 0;
         padding: 0;
         list-style: none;
         display: grid;
         gap: 0.9rem;
       }

       .support-points li {
         padding: 1rem 1rem 1rem 1.1rem;
         border-radius: var(--radius-md);
         background: rgba(255, 255, 255, 0.14);
         border: 1px solid rgba(255, 255, 255, 0.18);
       }

       .support-points strong {
         display: block;
         margin-bottom: 0.25rem;
       }

       .form-panel {
         background: var(--surface-strong);
       }

       .required-note {
         margin-top: 0.75rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       form {
         margin-top: 1.5rem;
       }

       .form-grid {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         display: grid;
         gap: 0.5rem;
       }

       label {
         font-weight: 700;
       }

       .required-indicator {
         color: var(--accent-strong);
       }

       input {
         width: 100%;
         min-height: 3.25rem;
         padding: 0.9rem 1rem;
         border: 1px solid var(--border);
         border-radius: var(--radius-sm);
         background: #fff;
         color: var(--text);
         font: inherit;
         transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
       }

       input::placeholder {
         color: #8a94aa;
       }

       input:hover {
         border-color: #aab7d3;
       }

       input:focus-visible,
       button:focus-visible {
         outline: 3px solid transparent;
         box-shadow: 0 0 0 4px rgba(51, 92, 255, 0.18);
         border-color: var(--accent);
       }

       .helper-text,
       .error-message {
         margin: 0;
         font-size: 0.95rem;
         line-height: 1.5;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-message {
         color: var(--error);
       }

       [hidden] {
         display: none !important;
       }

       .field-invalid input {
         border-color: var(--error);
       }

       .form-actions {
         display: flex;
         align-items: center;
         gap: 1rem;
         margin-top: 1.5rem;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.5rem;
')

