    <script>
      const form = document.getElementById("support-form");
      const statusRegion = document.getElementById("form-status");

      const fieldConfig = {
        fullName: {
          input: document.getElementById("fullName"),
          error: document.getElementById("fullName-error"),
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your full name.";
            }

            return "";
          },
        },
        email: {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your email address.";
            }

            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailPattern.test(value.trim())) {
              return "Error: Enter a valid email address, for example name@example.com.";
            }

            return "";
          },
        },
        phone: {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          helpId: "phone-help",
          validate(value) {
            if (!value.trim()) {
              return "";
            }

            const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
            if (!phonePattern.test(value.trim())) {
              return "Error: Enter a phone number using digits, spaces, dashes, or parentheses.";
            }

            return "";
          },
        },
      };

      function updateFieldState(fieldName) {
        const field = fieldConfig[fieldName];
        const message = field.validate(field.input.value);
        applyFieldPresentation(fieldName, message);

        return message;
      }

      function applyFieldPresentation(fieldName, message) {
        const field = fieldConfig[fieldName];
        const wrapper = field.input.closest(".form-field");
        const describedBy = [];

        if (field.helpId) {
          describedBy.push(field.helpId);
        }

        if (message) {
          field.error.textContent = message;
          field.error.hidden = false;
          describedBy.push(field.error.id);
          field.input.setAttribute("aria-invalid", "true");
          wrapper.classList.add("field-invalid");
        } else {
          field.error.textContent = "";
          field.error.hidden = true;
          field.input.removeAttribute("aria-invalid");
          wrapper.classList.remove("field-invalid");
        }

        if (describedBy.length > 0) {
          field.input.setAttribute("aria-describedby", describedBy.join(" "));
        } else {
          field.input.removeAttribute("aria-describedby");
        }
      }

      function clearFieldState(fieldName) {
        applyFieldPresentation(fieldName, "");
      }

      Object.keys(fieldConfig).forEach((fieldName) => {
        const field = fieldConfig[fieldName];

        field.input.addEventListener("input", () => {
          if (!field.error.hidden) {
            updateFieldState(fieldName);
          }

          if (statusRegion.textContent) {
            statusRegion.textContent = "";
            statusRegion.dataset.state = "";
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusRegion.textContent = "";
        statusRegion.dataset.state = "";

        const invalidFields = Object.keys(fieldConfig).filter((fieldName) => {
          return Boolean(updateFieldState(fieldName));
        });

        if (invalidFields.length > 0) {
          fieldConfig[invalidFields[0]].input.focus();
          return;
        }

        statusRegion.textContent = "Your support request has been sent.";
        statusRegion.dataset.state = "success";
        form.reset();

        Object.keys(fieldConfig).forEach((fieldName) => {
          clearFieldState(fieldName);
        });
      });
    </script>
